{
  "window_id": "w0002",
  "observed_failures": [
    {
      "filename": "034.jpg",
      "field": "date",
      "predicted": "2018-08-09",
      "symptom": "Date parsed from OCR line 'Data: 09/08/2018' but the receipt image clearly prints '09/03/2018'. Tesseract misread the month digit '3' as '8'. Agent accepted the first regex match without cross-validation."
    },
    {
      "filename": "074.jpg",
      "field": "total_amount",
      "predicted": "702.00",
      "symptom": "OCR line 'Total inel. of GBT 702.00' was accepted as the total. The receipt image shows 102.00 (subtotal/total/payment all = 102.00). Tesseract confused leading '1' with '7'. No multi-pass cross-check or arithmetic sanity check (subtotal 102.00 vs picked 702.00) was performed."
    },
    {
      "filename": "077.jpg",
      "field": "total_amount",
      "predicted": "23.26",
      "symptom": "Receipt contains two TOTAL-matching lines: 'Total (Inclusive of GST): 23.26' followed by 'Rounding Adj: -0.01' and a final 'TOTAL: 23.25'. The extractor picked the first TOTAL-tier match (pre-rounding) instead of the post-rounding final TOTAL. The task spec's priority ordering does not disambiguate repeated TOTAL hits within the same tier."
    },
    {
      "filename": "078.jpg",
      "field": "total_amount",
      "predicted": "",
      "symptom": "Extraction failed on the mangled 'GrandTota.' line and the agent wrote an empty string into the cell instead of a real null. Per task spec, failures must be null. Also: a pass with different preprocessing would likely have recovered 'Grand Total 92.80' / 'Total 92.80' lines."
    }
  ],
  "root_causes": [
    {
      "id": "rc_single_pass_ocr_no_consensus",
      "description": "Single Tesseract pass over the raw image is treated as ground truth. Common digit confusions (1↔7, 3↔8, 0↔O) in low-quality scans are not mitigated by multi-pass preprocessing, PSM variation, or cross-pass agreement voting. The multi_pass_ocr pattern is present in image-ocr but used only as a text-dump fallback, never as a consensus mechanism for specific fields.",
      "evidence_filenames": ["034.jpg", "074.jpg", "078.jpg"]
    },
    {
      "id": "rc_keyword_priority_underspecified_for_repeated_matches",
      "description": "Within a single priority tier, the extraction logic picks the first matching line rather than the last. On receipts that print both a pre-rounding 'Total (Inclusive of GST)' and a post-rounding final 'TOTAL', the pre-rounding value wins even though the final rounded TOTAL is the correct answer. Neither the task hint nor the current skills encode a 'prefer later/rounded TOTAL' rule."
    },
    {
      "id": "rc_no_arithmetic_sanity_check",
      "description": "Extracted totals are not cross-validated against other numeric cues on the same receipt (subtotal + GST ≈ total, or payment/cash ≈ total). 074.jpg has subtotal 102.00, payment 102.00, change 0.00 — an arithmetic check would have flagged 702.00 immediately."
    },
    {
      "id": "rc_null_vs_empty_string",
      "description": "On per-image extraction failure the pipeline writes an empty Python string ('') into the Excel cell instead of a real null (None). Task spec explicitly requires null on failure, and the strict-schema grader compares cell values; '' ≠ null. The original xlsx SKILL.md does not call out this contract; the candidate xlsx revision adds it but still lacks a verification step."
    },
    {
      "id": "rc_skill_coverage_gap_for_structured_field_extraction",
      "description": "Original image-ocr SKILL.md only produces free-form 'extracted_text' JSON. It has no built-in pattern for keyword-priority / exclusion-keyword extraction of dates and monetary totals from receipts, so each agent re-derives this logic ad hoc with varying rigor."
    }
  ],
  "skill_defects": [
    {
      "skill": "image-ocr",
      "defect": "No reusable structured-field extractor. Lacks: (a) priority+exclusion keyword matching module for receipts, (b) tie-breaker policy for repeated same-tier matches (prefer last/post-rounding), (c) multi-pass OCR consensus/voting on specific fields, (d) arithmetic cross-check against subtotal/tax/payment, (e) explicit digit-confusion mitigation (1/7, 3/8, 0/O) via upscale + sharpen + threshold variants for the specific line of interest."
    },
    {
      "skill": "image-ocr",
      "defect": "Date extraction is not spec'd. No guidance to collect all date candidates, normalize to ISO, and prefer the candidate confirmed by multiple preprocessing passes (which would have disambiguated 034.jpg's 09/03 vs 09/08)."
    },
    {
      "skill": "xlsx",
      "defect": "Original SKILL.md does not describe the 'strict-schema line-by-line grader' contract: exact sheet name, exact column order, no index, str vs float for amounts, and — critically — Python None for missing values rather than '' / 'NaN' / 'None'. It also lacks a self-verification step that re-reads the written file and asserts no empty-string sentinels in nullable columns."
    },
    {
      "skill": "xlsx",
      "defect": "The 'Use Formulas, Not Hardcoded Values' section is unconditionally stated and can mislead agents on extraction/output tasks where every cell must be a literal. Needs an explicit carve-out for strict-schema data outputs."
    },
    {
      "skill": "image-ocr + xlsx (integration)",
      "defect": "Neither skill links the two sides of the contract: the OCR skill should return None (not '') on failure, and the xlsx skill should refuse to coerce None to '' during write. The failure on 078.jpg crossed this seam."
    }
  ],
  "repair_recommendations": [
    {
      "target_skill": "image-ocr",
      "change": "Add a 'Structured Field Extraction (Receipts/Forms)' section with reusable code for: (1) tiered keyword priority list evaluated top-down; (2) exclusion keywords checked before any tier match; (3) within a tier, iterate ALL matching lines and prefer the LAST (post-rounding/final) occurrence; (4) two-line fallback when the keyword line has no number; (5) strip currency symbols/commas and return amounts as strings formatted with exactly two decimals; (6) return Python None on failure, never '' or 'NaN'.",
      "generalizes_beyond_this_task": true
    },
    {
      "target_skill": "image-ocr",
      "change": "Promote multi_pass_ocr from a text-dump helper to a consensus voter: run N preprocessing variants (grayscale+autocontrast, 2x upscale, invert, threshold at 100/128/160) × PSM {6,4,11}; for each candidate field (date, total) collect the parsed value from each pass and pick the majority value. Explicitly call out common Tesseract digit confusions (1↔7, 3↔8, 5↔6, 0↔O/8) and recommend upscaling + sharpening whenever a numeric line is accepted with only one supporting pass.",
      "generalizes_beyond_this_task": true
    },
    {
      "target_skill": "image-ocr",
      "change": "Add an optional arithmetic sanity check for monetary totals: if the extracted total disagrees with the receipt's subtotal + tax (±rounding) or with payment − change by more than a small tolerance, downgrade confidence and re-run extraction on an upscaled/thresholded variant before returning.",
      "generalizes_beyond_this_task": true
    },
    {
      "target_skill": "image-ocr",
      "change": "Add a Date Extraction subsection: enumerate accepted formats (DD/MM/YYYY, DD-MM-YYYY, YYYY-MM-DD, DD MMM YYYY, DD-MMM-YYYY, DD/MM/YY), normalize to ISO YYYY-MM-DD, and recommend cross-pass voting for ambiguous digits. On irreconcilable ambiguity return None rather than guess.",
      "generalizes_beyond_this_task": true
    },
    {
      "target_skill": "xlsx",
      "change": "Add a 'Strict-Schema Outputs (graded line-by-line)' section covering: exact file path, exact single sheet name, exact column order, index=False, forcing object dtype for string-formatted numeric columns so '47.70' is not coerced to 47.7, writing Python None for missing values (never '' / 'NaN' / 'None'), lexicographic row sort by the key column, and a mandatory post-write verification step that re-opens the file and asserts sheet name, column order, row count, dtype preservation, and absence of empty-string sentinels in nullable columns.",
      "generalizes_beyond_this_task": true
    },
    {
      "target_skill": "xlsx",
      "change": "Scope the 'Use Formulas, Not Hardcoded Values' rule to financial models and explicitly exempt strict-schema extraction outputs, where every cell must be a literal value matching the oracle byte-for-byte.",
      "generalizes_beyond_this_task": true
    },
    {
      "target_skill": "image-ocr",
      "change": "Document the per-image failure contract: catch all OCR/parse exceptions per image, emit a row with None for unparseable fields, and never let one bad image skip the row or substitute an empty-string placeholder. This closes the seam exposed by 078.jpg.",
      "generalizes_beyond_this_task": true
    }
  ],
  "confidence": {
    "level": "high",
    "basis": "Field-level feedback pinpoints the four failing (filename, field) pairs; the recorded OCR text in the trajectory shows exactly how each failure arose (misread digits for 034/074, two competing TOTAL lines for 077, mangled 'GrandTota' line plus empty-string write for 078). Root causes are directly observable in the source Agent's extracted text and in the delivered xlsx row for 078.jpg.",
    "unverified_assumptions": [
      "That multi-pass OCR with upscaling would in fact recover the correct digits on 034.jpg/074.jpg/078.jpg — plausible from the image quality but not empirically re-run in this diagnosis stage.",
      "That the oracle for 077.jpg expects the post-rounding TOTAL (23.25) rather than the pre-rounding 23.26; inferred from the image showing a final 'TOTAL: 23.25' line and from the grader marking 23.26 wrong."
    ]
  }
}
